Tool response:
Tool: find_audit_records
Description: Retrieve Brivo audit records for a specific data center within a date range.
Parameters:
    {
      "type": "object",
      "properties": {
        "data_center_name": {
          "type": "string",
          "description": "Name of the data center",
          "title": "Data Center Name"
        },
        "start_date": {
          "type": "string",
          "description": "Start date in YYYY-MM-DD format",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date in YYYY-MM-DD format",
          "title": "End Date"
        },
        "actions": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "description": "List of actions to filter by",
          "title": "Actions"
        }
      },
      "required": [
        "data_center_name",
        "start_date",
        "end_date"
      ]
    }
